import Foundation
import Vapor
import NIOCore

// FileService.swift - Async file management service
actor FileStorageActor {
    private let basePath: String
    private var activeOperations: Set<String> = []

    init(basePath: String) {
        self.basePath = basePath
    }

    func reservePath(_ relativePath: String) -> Bool {
        guard !activeOperations.contains(relativePath) else { return false }
        activeOperations.insert(relativePath)
        return true
    }

    func releasePath(_ relativePath: String) {
        activeOperations.remove(relativePath)
    }

    func resolvedBasePath() -> String {
        return basePath
    }
}

struct FileMetadata: Content {
    let name: String
    let size: Int64
    let created: Date
}

func configureRoutes(_ app: Application) throws {
    let storage = FileStorageActor(basePath: app.directory.publicDirectory + "uploads/")

    app.post("upload") { req async throws -> FileMetadata in
        let payload = try req.content.decode(UploadPayload.self)
        let sanitized = sanitizeFilename(payload.filename)

        guard !sanitized.isEmpty else {
            throw Abort(.badRequest, reason: "Invalid filename")
        }

        let reserved = await storage.reservePath(sanitized)
        guard reserved else {
            throw Abort(.conflict, reason: "File operation in progress")
        }

        defer {
            Task { await storage.releasePath(sanitized) }
        }

        let base = await storage.resolvedBasePath()
        let targetPath = base + sanitized

        // Security check: verify the resolved path is within base directory
        try await validatePathSafety(targetPath: targetPath, basePath: base)

        // Write file content
        let data = Data(base64Encoded: payload.contentBase64) ?? Data()
        try await writeFileAsync(path: targetPath, data: data)

        let attrs = try FileManager.default.attributesOfItem(atPath: targetPath)
        let size = attrs[.size] as? Int64 ?? 0
        let created = attrs[.creationDate] as? Date ?? Date()

        return FileMetadata(name: sanitized, size: size, created: created)
    }

    app.get("files", ":name") { req async throws -> Response in
        guard let name = req.parameters.get("name") else {
            throw Abort(.badRequest)
        }
        let sanitized = sanitizeFilename(name)
        guard !sanitized.isEmpty else {
            throw Abort(.badRequest, reason: "Invalid filename")
        }

        let base = await storage.resolvedBasePath()
        let filePath = base + sanitized

        // Validate before reading
        try await validatePathSafety(targetPath: filePath, basePath: base)

        // Read and return file
        let data = try await readFileAsync(path: filePath)
        return Response(status: .ok, body: .init(data: data))
    }
}

struct UploadPayload: Content {
    let filename: String
    let contentBase64: String
}

func sanitizeFilename(_ input: String) -> String {
    let cleaned = input
        .replacingOccurrences(of: "..", with: "")
        .replacingOccurrences(of: "/", with: "_")
        .replacingOccurrences(of: "\\", with: "_")

    let allowedChars = CharacterSet.alphanumerics.union(CharacterSet(charactersIn: "._-"))
    let filtered = cleaned.unicodeScalars.filter { allowedChars.contains($0) }
    return String(String.UnicodeScalarView(filtered))
}

func validatePathSafety(targetPath: String, basePath: String) async throws {
    // Check that the canonical path starts with the base path
    // We resolve the PARENT directory to allow new file creation
    let targetURL = URL(fileURLWithPath: targetPath)
    let parentDir = targetURL.deletingLastPathComponent().path

    let fm = FileManager.default

    // Resolve symlinks in parent directory
    let resolvedParent: String
    if fm.fileExists(atPath: parentDir) {
        resolvedParent = (parentDir as NSString).resolvingSymlinksInPath
    } else {
        throw Abort(.badRequest, reason: "Parent directory does not exist")
    }

    let resolvedBase = (basePath as NSString).resolvingSymlinksInPath

    guard resolvedParent.hasPrefix(resolvedBase) || resolvedParent == resolvedBase.dropLast() else {
        throw Abort(.forbidden, reason: "Path traversal detected")
    }

    // TOCTOU window: after validation, before file I/O
    // The async yield point here creates an exploitable gap
    await Task.yield()
}

func writeFileAsync(path: String, data: Data) async throws {
    try await withCheckedThrowingContinuation { (continuation: CheckedContinuation<Void, Error>) in
        DispatchQueue.global().async {
            do {
                try data.write(to: URL(fileURLWithPath: path))
                continuation.resume()
            } catch {
                continuation.resume(throwing: error)
            }
        }
    }
}

func readFileAsync(path: String) async throws -> Data {
    try await withCheckedThrowingContinuation { (continuation: CheckedContinuation<Data, Error>) in
        DispatchQueue.global().async {
            do {
                let data = try Data(contentsOf: URL(fileURLWithPath: path))
                continuation.resume(returning: data)
            } catch {
                continuation.resume(throwing: error)
            }
        }
    }
}
